<script setup lang="ts">
import{ref,onMounted}from'vue';import{http}from'../api/http';import type {Row} from '../shared/records'
const categories=ref<Row[]>([]),selected=ref<number[]>([]),largeText=ref(false),message=ref(''),error=ref(''),pending=ref(false)
onMounted(async()=>{try{categories.value=await http.get('/dish-categories');const data=await http.get<never,Row|null>('/auth/preferences');selected.value=data?.preferredCategoryIds??[];largeText.value=!!data?.largeText}catch(e){error.value=(e as Error).message}})
async function save(){pending.value=true;try{await http.put('/auth/preferences',{preferredCategoryIds:selected.value,largeText:largeText.value});sessionStorage.setItem('meal.largeText',String(largeText.value));window.dispatchEvent(new CustomEvent('meal:text-size',{detail:largeText.value}));message.value='偏好已保存'}catch(e){error.value=(e as Error).message}finally{pending.value=false}}
</script>
<template><section class="content-card" style="margin-top:24px"><h2>个人偏好</h2><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="message" :title="message" type="success" :closable="false"/><div class="form-stack"><p class="muted">这里保存当前账号的界面设置。家人的饮食偏好请在“老人绑定与补贴 → 健康与饮食偏好”中按老人维护。</p><label>账号收藏的菜品分类（不替代老人饮食档案）</label><el-select v-model="selected" multiple aria-label="个人偏好分类"><el-option v-for="category in categories" :key="category.id" :value="category.id" :label="category.name"/></el-select><el-checkbox v-model="largeText">默认使用大字模式</el-checkbox><el-button type="primary" :loading="pending" @click="save">保存个人偏好</el-button></div></section></template>
